    local t=Instance.new("TextLabel",titleBar) t.Text="⚡ INSTANT" t.Size=UDim2.new(1,-20,1,0) t.Position=UDim2.new(0,8,0,0) t.BackgroundTransparency=1 t.Font=Enum.Font.GothamBold t.TextSize=10 t.TextColor3=ACCENT t.TextXAlignment=Enum.TextXAlignment.Left
