    local btn=Instance.new("TextButton",main) btn.Name="StealBtn" btn.Size=UDim2.new(1,-8,1,-26) btn.Position=UDim2.new(0,4,0,22) btn.Text="STEAL HIGH $" btn.Font=Enum.Font.GothamBold btn.TextSize=12 btn.TextColor3=Color3.new(1,1,1) btn.BackgroundColor3=ACCENT btn.AutoButtonColor=false btn.ZIndex=101
    Instance.new("UICorner",btn).CornerRadius=UDim.new(0,8)
    local resize=Instance.new("Frame",main) resize.Name="Resize" resize.Size=UDim2.fromOffset(24,24) resize.Position=UDim2.new(1,-24,1,-24) resize.BackgroundTransparency=1 resize.Active=true resize.ZIndex=102
    local rl=Instance.new("TextLabel",resize) rl.Size=UDim2.fromScale(1,1) rl.BackgroundTransparency=1 rl.Text="⋰" rl.Font=Enum.Font.GothamBold rl.TextSize=14 rl.TextColor3=Color3.fromRGB(100,94,130) rl.TextXAlignment=Enum.TextXAlignment.Right rl.TextYAlignment=Enum.TextYAlignment.Bottom
    -- DRAG MOBILE + PC
    track(titleBar,function() return main.Position end,function(dx,dy,st,moved) if moved and st then local s=rootScale and rootScale.Scale or 1 main.Position=UDim2.new(st.X.Scale,st.X.Offset+dx/s,st.Y.Scale,st.Y.Offset+dy/s) end end)
    track(main,function() return main.Position end,function(dx,dy,st,moved) if moved and st then local s=rootScale and rootScale.Scale or 1 main.Position=UDim2.new(st.X.Scale,st.X.Offset+dx/s,st.Y.Scale,st.Y.Offset+dy/s) end end)
    -- RESIZE MOBILE + PC
    local minSize=Vector2.new(110,56) local maxSize=Vector2.new(220,120)
    track(resize,function() return main.Size end,function(dx,dy,st) local s=rootScale and rootScale.Scale or 1 local nw=math.clamp(st.X.Offset+dx/s,minSize.X,maxSize.X) local nh=math.clamp(st.Y.Offset+dy/s,minSize.Y,maxSize.Y) main.Size=UDim2.fromOffset(nw,nh) end)
    -- INSTANT STEAL ACTION
    btn.MouseButton1Click:Connect(function()
        local folder=workspace:FindFirstChild("AnimalPickups") if not folder then return end
        local best=nil local bestCash=0
        for _,m in ipairs(folder:GetChildren()) do
            if m:IsA("Model") then
                local c=parseCash(getCashPerSecond(m))
                if c>bestCash then bestCash=c best=m end
            end
        end
        if not best then Window.Notify("INSTANT","No Target",DIM,2) return end
        local hrp=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not hrp then return end
        local pos=getOffsetPos(best) if not pos then pos=getBasePos(best) end
        if pos then
            -- TELEPORT CEPAT KE TARGET
            hrp.CFrame=CFrame.new(pos)
            task.wait(0.06)
            for i=1,3 do fireSteal(best) touchSteal(best) pressE() task.wait(0.04) end
            task.wait(0.1)
            -- TELEPORT CEPAT KE BASE
            hrp.CFrame=CFrame.new(SAFE_BASE_POS)
            Window.Notify("INSTANT STEAL",best.Name.." $"..bestCash,ACCENT,2)
        end
    end)
    instantGui=gui
end

