followToggle.btn.MouseButton1Click:Connect(function() followEnabled=not followEnabled if followEnabled then if not selectedFollowPlayer or selectedFollowPlayer=="No Player" then Window.Notify("ERROR","Pilih player dulu!",Color3.fromRGB(248,113,113),2) followEnabled=false return end tw(followToggle.track,{BackgroundColor3=ACCENT},0.2):Play() tw(followToggle.dot,{Position=UDim2.new(1,-21,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(followToggle.accent,{BackgroundColor3=ACCENT},0.2):Play() Window.Notify("FOLLOW","Follow ON: "..selectedFollowPlayer,ACCENT,2) task.spawn(function() while followEnabled do if selectedFollowPlayer then local target=Players:FindFirstChild(selectedFollowPlayer) if target and target.Character and target.Character:FindFirstChild("HumanoidRootPart") then local hrp=target.Character.HumanoidRootPart walkDirect(Vector3.new(hrp.Position.X,3.5,hrp.Position.Z),hrp.Position,false) end end task.wait(0.15) end end) else tw(followToggle.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},0.2):Play() tw(followToggle.dot,{Position=UDim2.new(0,3,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(followToggle.accent,{BackgroundColor3=Color3.fromRGB(60,55,80)},0.2):Play() Window.Notify("FOLLOW","OFF",DIM,2) end end)

local fastBreakOn=false local fastBreakConn=nil
